input.command:
$h='0d6ca4607eaf'
$p="data\replay\$h"
Get-ChildItem $p | Select-Object Name, Length
if (Test-Path "$p\opencode.ndjson") { Write-Output "ndjson_lines=$((Get-Content "$p\opencode.ndjson" | Measure-Object -Line).Lines)" }
if (Test-Path "$p\opencode.err") { Write-Output "err_bytes=$((Get-Item "$p\opencode.err").Length)" }

python -c "
import json
from pathlib import Path
from collections import Counter
p=Path('data/replay/0d6ca4607eaf/opencode.ndjson')
tools=[]
types=Counter()
for line in p.read_text(encoding='utf-8', errors='replace').splitlines():
    line=line.strip()
    if not line: continue
    try: o=json.loads(line)
    except json.JSONDecodeError: continue
    t=o.get('type') or o.get('event') or ''
    types[str(t)[:40]]+=1
    # common shapes
    for k in ('name','tool','toolName'):
        v=o.get(k)
        if isinstance(v,str) and 0<len(v)<80: tools.append(v)
    part=o.get('part') if isinstance(o.get('part'), dict) else {}
    if isinstance(part.get('tool'), str): tools.append(part['tool'])
    if isinstance(part.get('name'), str): tools.append(part['name'])
    d=o.get('data') if isinstance(o.get('data'), dict) else {}
    if isinstance(d.get('tool'), str): tools.append(d['tool'])
    if isinstance(d.get('name'), str) and d.get('type') in ('tool','tool_use','tool_call'): tools.append(d['name'])
print('types', types.most_common(15))
print('tools', tools[:30], 'n', len(tools))
print('keys_sample', list(json.loads(p.read_text(encoding='utf-8', errors='replace').splitlines()[0]).keys()) if p.read_text(encoding='utf-8').strip() else None)
"

$p='data\replay\6eb8631b71ff\opencode.ndjson'
if (Test-Path $p) {
  python -c "
from pathlib import Path
import json
from src.score_session import score_seq
raw=Path(r'data/replay/6eb8631b71ff/opencode.ndjson').read_bytes()
text=raw.decode('utf-16') if raw[:2] in (b'\xff\xfe', b'\xfe\xff') else raw.decode('utf-8','replace')
tools=[]
for line in text.splitlines():
    line=line.strip()
    if not line.startswith('{'): continue
    try: o=json.loads(line)
    except: continue
    if o.get('type')=='tool_use':
        part=o.get('part') if isinstance(o.get('part'), dict) else o
        n=part.get('tool') or part.get('name')
        if isinstance(n,str): tools.append(n)
print('n', len(tools), tools[:20])
s=score_seq(tools)
print(s.get('work_match'), s.get('fail_mask'))
"
} else { Write-Output 'missing' }
